# Packs Get-PilotLogExtract.ps1 into one double-click .cmd (SHA-256 self-check, in-memory, read-only).
param([string]$Script = (Join-Path $PSScriptRoot 'Get-PilotLogExtract.ps1'), [string]$Out = (Join-Path $PSScriptRoot '..\dist\itmgmt-pilot\ITMANAGAMENT-LogExtract.cmd'))
$ErrorActionPreference = 'Stop'
$bytes = [IO.File]::ReadAllBytes($Script); $sha = ([BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash($bytes)) -replace '-', '').ToLower(); $b64 = [Convert]::ToBase64String($bytes)
$boot = '$t=[IO.File]::ReadAllText(''%~f0''); $mb=''#PAYLOAD''+''-BEGIN''; $me=''#PAYLOAD''+''-END''; $a=$t.IndexOf($mb); $e=$t.LastIndexOf($me); $nl=$t.IndexOf([char]10,$a); $h=$t.Substring($a,$nl-$a).Trim().Split('' '')[1]; $by=[Convert]::FromBase64String($t.Substring($nl+1,$e-$nl-1).Trim()); $sha=([BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash($by)) -replace ''-'','''').ToLower(); if($sha -ne $h){ Write-Host ''SHA-256 MISMATCH - not running.'' -ForegroundColor Red; exit 9 }; $sb=[ScriptBlock]::Create([Text.Encoding]::UTF8.GetString($by)); & $sb -ReportDir ''%~dp0'''
$cmd = "@echo off`r`ntitle LIDER Collector log extract (read-only)`r`necho READ ONLY: copies the Collector log lines of the pilot window to a file and the clipboard. Nothing is changed.`r`necho.`r`npowershell -NoProfile -ExecutionPolicy Bypass -Command `"$boot`"`r`necho.`r`npause`r`nexit /b`r`n#PAYLOAD-BEGIN $sha`r`n$b64`r`n#PAYLOAD-END`r`n"
New-Item -ItemType Directory -Force (Split-Path $Out) | Out-Null; [IO.File]::WriteAllText($Out, $cmd, (New-Object Text.ASCIIEncoding)); "built $((Resolve-Path $Out).Path) sha256 $((Get-FileHash $Out -Algorithm SHA256).Hash.ToLower().Substring(0,16))"
